#include <stdint.h>

#include "bsp/memory.h"
#include "board_config.h"

/*
 * Reports how much of the RAM above ThreadX's first unused address the
 * application may claim. Only this board knows what sits above it, which is
 * why the application never has to.
 *
 * The two shipped targets show the two shapes this takes:
 *
 *   - NUCLEO-F401RE keeps its main stack at the top of SRAM, so it clamps the
 *     region below a fixed reservation.
 *   - PolarFire SoC keeps its boot stack below the first unused address and
 *     only has to skip the C heap reservation.
 *
 * TODO: Subtract whatever this board reserves. Anything the C heap, the main
 * stack, or a memory-mapped window owns must NOT appear in the returned
 * region - an application will allocate every byte of it.
 */
void bsp_ram_region(void *first_unused, void **base, size_t *size)
{
    /*
     * MISRA C:2012 Rule 11.4 deviation: converting between a pointer and an
     * integer is unavoidable when comparing against an absolute address, which
     * C cannot express on pointers to distinct objects.
     */
    const uintptr_t start = (uintptr_t)first_unused;
    const uintptr_t end   = (uintptr_t)BSP_RAM_END - (uintptr_t)BSP_MAIN_STACK_RESERVE;

    *base = first_unused;
    *size = (end > start) ? (size_t)(end - start) : (size_t)0U;
}
